from pathlib import Path
import re

import pymupdf
import pytest
from fastapi.testclient import TestClient

from app.injection.pdf import extract_pdf_text, read_pdf_metadata
from app.injection.schemas import DefectType
from app.injection.store import get_document, get_document_file_path, reset_sample_documents
from app.main import app

client = TestClient(app)

# Existing text PDF in data/templates/ (not generated by the app).
DOC_ID = "C001_CertIncumbency"
TEXT_FIELD = "golden_harvest_trading_pte_ltd"
NUMERIC_FIELD = "100_000"


@pytest.fixture(autouse=True)
def _reset_documents() -> None:
    reset_sample_documents()


def _inject(document_id: str, field_name: str | None, defect_type: DefectType):
    payload: dict = {
        "document_id": document_id,
        "defect_type": defect_type.value,
    }
    if field_name is not None:
        payload["field_name"] = field_name
    return client.post("/api/dev/inject", json=payload)


def _field_for(defect_type: DefectType) -> str:
    return NUMERIC_FIELD if defect_type == DefectType.NUMERICAL else TEXT_FIELD


@pytest.mark.parametrize("defect_type", list(DefectType))
def test_each_defect_type_can_be_injected_into_a_pdf(defect_type: DefectType) -> None:
    before = get_document(DOC_ID)
    assert before is not None
    field_name = _field_for(defect_type)

    response = _inject(DOC_ID, field_name, defect_type)

    assert response.status_code == 200
    payload = response.json()
    assert payload["defect_type"] == defect_type.value
    assert payload["field_name"] == field_name
    assert payload["defect_count"] == len(before.defects) + 1
    assert payload["filename"] == f"{DOC_ID}.pdf"
    pdf_path = Path(get_document_file_path(DOC_ID) or "")
    assert pdf_path.exists()
    assert pdf_path.read_bytes().startswith(b"%PDF")


@pytest.mark.parametrize("defect_type", list(DefectType))
def test_single_defect_injection_succeeds(defect_type: DefectType) -> None:
    field_name = _field_for(defect_type)
    response = _inject(DOC_ID, field_name, defect_type)

    assert response.status_code == 200
    payload = response.json()
    assert payload["defect_type"] == defect_type.value
    assert payload["field_name"] == field_name
    if defect_type in {DefectType.NUMERICAL, DefectType.SPELLING}:
        assert payload["before_text"] != payload["after_text"]


def test_numerical_injection_updates_pdf_bytes() -> None:
    before = get_document(DOC_ID)
    assert before is not None
    original = before.fields[NUMERIC_FIELD].text

    response = _inject(DOC_ID, NUMERIC_FIELD, DefectType.NUMERICAL)

    assert response.status_code == 200
    after_text = response.json()["after_text"]
    assert after_text != original
    text = extract_pdf_text(Path(get_document_file_path(DOC_ID) or ""))
    assert after_text in text


def test_spelling_injection_updates_pdf_bytes() -> None:
    before = get_document(DOC_ID)
    assert before is not None
    original = before.fields[TEXT_FIELD].text

    response = _inject(DOC_ID, TEXT_FIELD, DefectType.SPELLING)

    assert response.status_code == 200
    after_text = response.json()["after_text"]
    assert after_text != original
    text = extract_pdf_text(Path(get_document_file_path(DOC_ID) or ""))
    assert after_text in text
    assert original not in text


def test_metadata_injection_updates_pdf_metadata() -> None:
    before_meta = read_pdf_metadata(Path(get_document_file_path(DOC_ID) or ""))
    response = _inject(DOC_ID, TEXT_FIELD, DefectType.METADATA)

    assert response.status_code == 200
    after_meta = read_pdf_metadata(Path(get_document_file_path(DOC_ID) or ""))
    assert after_meta != before_meta
    assert any(
        after_meta.get(key) != before_meta.get(key)
        for key in ("author", "creator", "title", "subject")
    )


def test_rejects_unknown_field_on_document() -> None:
    response = _inject(DOC_ID, "net_pay", DefectType.FONT)

    assert response.status_code == 400
    assert "not found" in response.json()["detail"]


def test_rejects_unknown_document() -> None:
    response = _inject("doc-does-not-exist", "closing_balance", DefectType.NUMERICAL)

    assert response.status_code == 404


def test_inject_without_field_picks_a_random_target() -> None:
    response = _inject(DOC_ID, None, DefectType.NUMERICAL)

    assert response.status_code == 200
    payload = response.json()
    document = get_document(DOC_ID)
    assert document is not None
    assert payload["field_name"] in document.fields
    assert re.search(r"\d", payload["before_text"] or "")
    assert payload["before_text"] != payload["after_text"]


def test_inject_spelling_without_field_picks_a_word() -> None:
    response = _inject(DOC_ID, None, DefectType.SPELLING)

    assert response.status_code == 200
    assert response.json()["field_name"] in get_document(DOC_ID).fields


def test_templates_folder_pdf_is_auto_registered() -> None:
    from app.injection.pdf import TEMPLATES_DIR

    custom = TEMPLATES_DIR / "C001_CertIncumbency_test.pdf"
    _make_custom_pdf(custom)
    try:
        reset_sample_documents()
        with_suffix = client.get("/api/dev/documents/C001_CertIncumbency_test.pdf/fields")
        without_suffix = client.get("/api/dev/documents/C001_CertIncumbency_test/fields")

        assert with_suffix.status_code == 200
        assert without_suffix.status_code == 200
        assert len(with_suffix.json()) >= 1
    finally:
        custom.unlink(missing_ok=True)
        Path(get_document_file_path("C001_CertIncumbency_test") or "").unlink(missing_ok=True)
        reset_sample_documents()


def test_fields_endpoint() -> None:
    fields = client.get(f"/api/dev/documents/{DOC_ID}/fields")

    assert fields.status_code == 200
    payload = fields.json()
    names = {item["field_name"] for item in payload}
    assert TEXT_FIELD in names
    assert NUMERIC_FIELD in names
    assert all(item["source"] == "pdf_text" for item in payload)


def _make_custom_pdf(path: Path) -> None:
    doc = pymupdf.open()
    page = doc.new_page(width=400, height=300)
    page.insert_text((72, 100), "Custom Tenant", fontsize=12, fontname="helv")
    page.insert_text((72, 140), "Rent 1500.00", fontsize=12, fontname="helv")
    doc.set_metadata({"title": "Tenancy Agreement", "author": "Broker"})
    doc.save(path)
    doc.close()
